    /* Analysis heatmap — OKLCH colour ramp tokens */
    --bn-heat-frustration-h: 55;
    --bn-heat-confusion-h: 30;
    --bn-heat-doubt-h: 295;
    --bn-heat-surprise-h: 75;
    --bn-heat-satisfaction-h: 155;
    --bn-heat-delight-h: 170;
