    --bn-colour-delight: var(--bn-sentiment-delight);
    --bn-colour-delight-bg: var(--bn-sentiment-delight-bg);

    /* Layout */
    --bn-max-width: 52rem;
    --bn-quote-max-width: 23rem;   /* card reading measure — ~5 words/line */
    --bn-grid-gap: 1.25rem;        /* gap between grid columns */
    --bn-flow-tolerance: 5em;      /* grid-lanes masonry: how much height imbalance
