    --bn-radius-pill: 999px;

    /* ── Inline edit fields — READ THIS BEFORE STYLING A NEW ONE ──────────
     *
     * An inline edit field is a piece of text the researcher can click into
     * and retype: a theme heading, a session name, a code group's title, a
     * code. There are exactly TWO treatments and the choice is mechanical,
     * decided by the GROUND the field sits on, not by which lens you are in:
     *
     *   field on page background  →  --bn-field-edit-fill-on-page  (tints up)
     *   field on a tinted surface →  --bn-field-edit-fill-on-tint  (blanks to
     *                                                               neutral)
     *
     * Both carry --bn-field-edit-edge at 1px. The fill inverts because the
     * ground does; the edge never changes, so the signal is one signal.
     * Border or outline is yours to pick — outline for a span in running
     * prose (it costs no layout and will not reflow the line), border for
     * something that already has a box. That is a mechanism, not a meaning.
     *
     * DO NOT invent a third fill. Two surfaces got one each before these
     * tokens existed (a quote-bg tint, a page-bg blank) and two more got
     * nothing at all, which is how "is this field live?" came to have four
     * answers on one screen.
     *
     * THE ONE EXEMPTION is quote cropping — `.crop-editable` and the bracket
     * handles in molecules/editable-text.css. That is not "edit this text",
     * it is "move this boundary", it was designed as a single signal with the
     * burnt-amber brackets, and it keeps --bn-colour-crop-bg. Do not reach
     * for that yellow for anything else, and do not restyle crop to match
     * these: a different verb is allowed a different look. The token was
     * called --bn-colour-editing-bg until 20 Sep 2026; it was renamed
     * because a token named for a state it must not be used in is how the
     * four-answers-on-one-screen problem started. */
    --bn-field-edit-edge: var(--bn-colour-accent);
    --bn-field-edit-fill-on-page: var(--bn-colour-quote-bg);
    --bn-field-edit-fill-on-tint: var(--bn-colour-bg);
    --bn-field-edit-radius: var(--bn-radius-sm);
    --bn-field-edit-offset: 1px;

    /* Section-divider keyline — the colour of the h2 / .section-heading /
       .framework-section-header bottom rules and the header <hr>. Aliases
       --bn-colour-border by default (visible); set to `transparent`
       (globally here, or per-surface) to hide every section divider WITHOUT
       moving anything — the 1px box still lays out, it just stops painting.
       The reversible borders-off experiment. Table-header (th) rules keep
       --bn-colour-border (data-grid chrome, not a section divider).
       See docs/design-lens-template.md § Keylines. */
    --bn-colour-keyline: var(--bn-colour-border);

    /* Transitions */
    --bn-transition-fast: 0.15s ease;
    --bn-transition-normal: 0.2s ease;
    --bn-transition-slow: 0.3s ease;

    /* Focus Mode — the distraction-free reading state (templates/focus-mode.css,
       docs/design-focus-mode.md). Structural, NOT palette-overridable: the whole
       transform is colour-free by design, which is what lets it compose with
       every palette × appearance with zero per-palette overrides. Deliberately
       here and not in colors/_contract.css — a Focus token in the contract would
       oblige every future palette author to answer a question the feature
       doesn't ask. "Dusk, not a light-switch": no overshoot, no bounce — the
       wrong register for reading evidence. */
    --bn-focus-ghost-opacity: 0.14;
    --bn-focus-heading-opacity: 0.4;
    --bn-focus-dur: 320ms;
    --bn-focus-ease: ease-in-out;
    /* How much of a receded card's outline survives — the border is mixed
       toward transparent by the remainder. One number for both lenses (the
       quote card's left edge, the signal card's box and fused seam); it was a
       literal 40% in two places until the Signals lens made it three. */
    --bn-focus-outline-mix: 40%;

    /* Thinking-shimmer — the "work in progress" travelling-sheen for text.
       Shared cross-surface spec, locked 18 Jul 2026 (docs/design-motion.md
       §4.7.1). Consuming surfaces set --bn-shimmer-base (resting text colour)
       and --bn-shimmer-peak (the pole the band moves toward: white where text
       is dark, the surface background where text is light) so the sheen has
       headroom in every theme. See atoms/shimmer.css. */
    --bn-shimmer-contrast: 5%;    /* band peak = 5% from base toward the peak pole */
    --bn-shimmer-band: 34%;       /* feathered band width, as % of the gradient */
    --bn-shimmer-angle: 100deg;   /* slight off-horizontal tilt */
    --bn-shimmer-sweep: 1800ms;   /* travel time (documentation; keyframe encodes the split) */
    --bn-shimmer-gap: 900ms;      /* dark hold between sweeps (documentation) */
    --bn-shimmer-period: 2700ms;  /* sweep + gap — the animation duration */
    --bn-shimmer-easing: ease-in-out;

    /* Legacy aliases — used by inline styles in generated HTML.
       Theme authors: override the --bn-* versions above;
       these aliases follow automatically. */
    --font-body: var(--bn-font-body);
    --font-mono: var(--bn-font-mono);
    --colour-bg: var(--bn-colour-bg);
    --colour-text: var(--bn-colour-text);
    --colour-muted: var(--bn-colour-muted);
    --colour-border: var(--bn-colour-border);
    --colour-accent: var(--bn-colour-accent);
    --colour-quote-bg: var(--bn-colour-quote-bg);
    --colour-badge-bg: var(--bn-colour-badge-bg);
    --colour-badge-text: var(--bn-colour-badge-text);
    --colour-confusion: var(--bn-colour-confusion);
    --colour-frustration: var(--bn-colour-frustration);
    --colour-delight: var(--bn-colour-delight);
    --colour-suggestion: var(--bn-colour-suggestion);
    --max-width: var(--bn-max-width);
}

