/* ════ bristlenose/theme/tokens-typography.css — lines 1–88 ════ */
/* Typography tokens — web defaults (Inter Variable from Google Fonts).
   Desktop overrides are in tokens-desktop.css.

   Scale D — 8 stops. Semantic intent:
   - label (13px) = app's voice (chrome, UI labels, navigation, context)
   - body  (15px) = participant's voice (quote text, transcript segments)

   Archive of previous scale: tokens-typography-v1.css */

:root {
    /* Font family — Inter Variable loaded from Google Fonts (see index.html).
       Fallback chain: Segoe UI Variable (Win 11), Segoe UI (Win 10),
       system-ui, SF Pro (macOS), CJK families. */
    --bn-font-body: "Inter", "Segoe UI Variable", "Segoe UI", system-ui, -apple-system,
        "Hiragino Kaku Gothic ProN", "Hiragino Sans",   /* macOS Japanese */
        "Yu Gothic UI",                                  /* Windows Japanese */
        "Malgun Gothic",                                 /* Windows Korean */
        "Apple SD Gothic Neo",                           /* macOS Korean */
        "Noto Sans CJK JP", "Noto Sans CJK KR",         /* Linux CJK */
        sans-serif;
    /* One mono stack for both scales (docs/design-monospace-roles.md §4, §6). No "SF Mono" by
       name: it resolves only on Macs with Apple's developer download, so it made the developer's
       view differ from every researcher's. WebKit reaches the system SF Mono via ui-monospace;
       Chromium on a Mac has no ui-monospace and takes Menlo; Windows 11 Cascadia Mono, Windows 10
       Consolas; Linux DejaVu. The generic is last and reached nowhere measured: it is Courier in
       Chromium on a Mac and Courier New in Windows 10's Edge. */
    --bn-font-mono: ui-monospace, Menlo, "Cascadia Mono", Consolas, "DejaVu Sans Mono", monospace;

    /* Font weight scale — tuned for variable fonts (Inter, SF Pro, Segoe UI Variable).
       On static fonts (Win 10 Segoe UI), 370/420→400 and 490→400 — acceptable degradation. */
    --bn-weight-light: 370;      /* subordinate text (sidebar nav links, secondary lists) */
    --bn-weight-normal: 420;     /* body text, descriptions, quote content */
    --bn-weight-emphasis: 490;   /* headings, labels, section titles */
    --bn-weight-starred: 520;    /* starred quotes — pop above emphasis, below strong */
    --bn-weight-semibold: 600;   /* a chosen word in a text-only switch (picker scope) */
    --bn-weight-strong: 700;     /* delete buttons, page title, action glyphs */

    /* Icon stroke = the stem of the text beside it, as a fraction of the font size
       (docs/design-icon-system.md § Weight; measured on Inter and SF Pro, which agree
       to 2%). A context set in a heavier weight sets --bn-icon-stem beside its
       font-weight. No light value: the SPA's Inter is served 400..700, so 370 renders 400. */
    --bn-icon-stem-normal: 0.092;
    --bn-icon-stem-emphasis: 0.106;
    --bn-icon-stem-starred: 0.111;
    --bn-icon-stem-semibold: 0.127;
    --bn-icon-stem-strong: 0.146;
    --bn-icon-stem: var(--bn-icon-stem-normal);

    /* Monospace weights — three values, chosen against measured rendering on every face the
       stack reaches (docs/design-monospace-roles.md §6). 400–490 is Regular in Menlo, Consolas
       and Cascadia Mono and varies only in SF Mono; Windows matches the nearest weight, so
       Consolas turns Bold at 550 and Cascadia SemiBold at 500. */
    --bn-weight-mono: 400;          /* every mono role at rest */
    --bn-weight-mono-tag: 460;      /* tags, light appearance: SF Mono +9%, Regular elsewhere; 400 in dark (below) */
    --bn-weight-mono-emphasis: 560; /* the one step up (a path that names the screen): Bold in Menlo and Consolas */

    /* Typography scale — 8 stops, size + line-height pairs.
       Line-height decreases as size increases (Bringhurst principle:
       large letterforms provide visual anchoring, need less leading). */
    --bn-text-micro:       0.6rem;      /* 9.6px  — delete ×, confidence badges */
    --bn-text-micro-lh:    1.2;
    --bn-text-badge:       0.72rem;     /* 11.5px — badges, group headers, tag counts */
    --bn-text-badge-lh:    1.3;
    --bn-text-caption:     0.75rem;     /* 12px   — footnotes, footer, modal footer, kbd */
    --bn-text-caption-lh:  1.4;
    --bn-text-label:       0.8125rem;   /* 13px   — toolbar, filters, context, timecodes (app voice) */
    --bn-text-label-lh:    1.45;
    --bn-text-body:        0.9375rem;   /* 15px   — quote text, transcript segments (participant voice) */
    --bn-text-body-lh:     1.5;
    --bn-text-heading:     1.125rem;    /* 18px   — section headings, h3, modal titles */
    --bn-text-heading-lh:  1.3;
    --bn-text-title:       1.375rem;    /* 22px   — page titles, h2, logotype */
    --bn-text-title-lh:    1.25;
    --bn-text-display:     1.75rem;     /* 28px   — report h1 */
    --bn-text-display-lh:  1.2;
}

/* Tags drop to Regular in the dark appearance: light text on a dark tint already reads heavier,
   and dark tags measure 6.2–9.3:1 against light's 3.1–5.2:1 (docs/design-monospace-roles.md).
   font-weight cannot follow light-dark(), so the token follows the two scopes the palettes use. */
[data-theme="dark"] {
    --bn-weight-mono-tag: var(--bn-weight-mono);
}
@media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
        --bn-weight-mono-tag: var(--bn-weight-mono);
    }
}

/* ════ bristlenose/theme/tokens-desktop.css — lines 1–70 ════ */
/* Desktop typography overrides — SF Pro for macOS native feel.
   Active when data-platform="desktop" is set on <html> AND the user hasn't
   opted back to Inter. The macOS app sets data-platform via
   BRISTLENOSE_PLATFORM=desktop; the Appearance ▸ Typography setting writes
   BRISTLENOSE_TYPOGRAPHY, and "inter" makes the server emit
   data-typography="inter" — which this block's :not() excludes, so the cascade
   falls back to :root (Inter). On web/CLI neither var is set, so this never
   matches: SF Pro is licensed for Apple platforms only, Inter ships everywhere.

   SF Pro is a system font on macOS — no download needed.
   SF Pro Text is optimised for body sizes (<20pt), SF Pro Display for headings (≥20pt).
   -apple-system resolves to SF Pro automatically on macOS.

   Scale — calibrated against the live macOS AppKit ladder via the Type Parity
   Inspector (Debug ▸ Type Parity Inspector), macOS 26.4.1 @2x, Color LCD. Each
   bn stop is width-matched to its measured native style (Δ ≈ 0px), so the labels
   below are the *real* macOS styles (the old "Apple callout = 15px" label was
   wrong — callout is 12pt):
   - micro:   caption2     (10px)
   - badge:   subheadline  (11px)
   - caption: callout      (12px)
   - label:   body         (13px)  — app voice
   - body:    title3       (15px)  — participant voice (quotes + transcript)
   - heading: title2       (17px)
   - title:   title1       (22px)
   - display: largeTitle   (26px)

   Line-heights are Apple's absolute leadings expressed as size-relative ratios,
   except body — loosened slightly by eye (1.4) for reading comfort. --bn-track-* carries Apple's per-size
   tracking — empirically ≈0 across this range (only micro is non-zero), and
   currently unconsumed (no letter-spacing wired yet). Sizes are kept in rem so
   they still honour the user's root font-size; the px in each comment is the
   value at the default 16px root (the condition this was calibrated under).
   Re-true on a different scale/colour profile. Archive: tokens-desktop-v1.css */

[data-platform="desktop"]:not([data-typography="inter"]) {
    /* Font family — SF Pro via -apple-system, no Google Fonts needed */
    --bn-font-body: -apple-system, "SF Pro Text", "SF Pro", system-ui,
        "Hiragino Kaku Gothic ProN", "Hiragino Sans",
        sans-serif;
    /* No --bn-font-mono override: the :root stack reaches the system SF Mono via ui-monospace. */

    --bn-text-micro:       0.625rem;    /* 10px  — macOS caption2 */
    --bn-text-micro-lh:    1.300;
    --bn-track-micro:      0.013em;
    --bn-text-badge:       0.6875rem;   /* 11px  — macOS subheadline */
    --bn-text-badge-lh:    1.273;
    --bn-track-badge:      0;
    --bn-text-caption:     0.75rem;     /* 12px  — macOS callout */
    --bn-text-caption-lh:  1.250;
    --bn-track-caption:    0;
    --bn-text-label:       0.8125rem;   /* 13px  — macOS body */
    --bn-text-label-lh:    1.231;
    --bn-track-label:      0;
    --bn-text-body:        0.9375rem;   /* 15px  — macOS title3 */
    --bn-text-body-lh:     1.4;         /* looser than title3's 1.333 — tuned by eye in the stress-bench for reading comfort (participant voice) */
    --bn-track-body:       0;
    --bn-text-heading:     1.0625rem;   /* 17px  — macOS title2 */
    --bn-text-heading-lh:  1.294;
    --bn-track-heading:    0;
    --bn-text-title:       1.375rem;    /* 22px  — macOS title1 */
    --bn-text-title-lh:    1.182;
    --bn-track-title:      0;
    --bn-text-display:     1.625rem;    /* 26px  — macOS largeTitle */
    --bn-text-display-lh:  1.231;
    --bn-track-display:    0;

    /* Weight scale — SF Pro optical weights at same numeric values.
       No change needed — Inter and SF Pro share the weight axis range. */
}

/* ════ bristlenose/theme/colors/palette-default.css — lines 1–170 ════ */
/* palette-default — Bristlenose's standard blue/grey colour theme.
   This is the web-mode default palette, loaded as :root fallback.
   Tokens defined here are overridden by any active [data-color-theme] palette.

   To create a new theme: copy this file, change the selector to
   [data-color-theme="your-theme"], and remap every token.
   See _contract.css for the full list of required tokens. */

:root,
[data-color-theme="default"] {
    /* Colour palette */
    --bn-colour-bg: #ffffff;
    --bn-colour-text: #1a1a1a;
    --bn-colour-muted: #6b7280;
    --bn-colour-border: #e5e7eb;
    --bn-colour-accent: #007aff;
    --bn-colour-hover: #e8f0fe;
    --bn-colour-inspector-bg: #f9f9fa;          /* Inspector chrome — Xcode Tahoe's flat inspector tint (~2% off white) */

    /* Semantic surfaces */
    --bn-colour-quote-bg: #f9fafb;
    --bn-colour-badge-bg: #f3f4f6;
    --bn-colour-badge-text: #374151;
    --bn-colour-user-tag-bg: #f3f4f6;
    --bn-colour-user-tag-text: #4b5563;
    --bn-colour-crop-bg: #fffbe6;
    --bn-crop-handle-colour: #c4850a;
    --bn-crop-handle-hover: #a06d08;
    --bn-colour-active-bg: #f0fdf4;
    --bn-colour-highlight: #fef08a;

    /* Destructive action */
    --bn-colour-negative: #dc2626;

    /* Success and caution — the other two semantic kinds */
    --bn-colour-positive: #16a34a;
    --bn-colour-warning: #f59e0b;

    /* Playback-sync glow */
    --bn-glow-colour: rgba(0, 122, 255, 0.06);
    --bn-glow-colour-strong: rgba(0, 122, 255, 0.11);

    /* Minimap */
    --bn-minimap-quote: #e5e7eb;
    --bn-minimap-heading: #b0b5bd;
    --bn-minimap-viewport-bg: rgba(0, 122, 255, 0.15);
    --bn-minimap-viewport-border: rgba(0, 122, 255, 0.3);

    /* Transcript coverage bar */
    --bn-coverage-report: #93b4f4;
    --bn-coverage-moderator: #d97706;
    --bn-coverage-omitted: #d1d5db;

    /* Group card background tints */
    --bn-group-none: #f9fafb;

    /* Micro histogram bar — neutral */
    --bn-bar-none: #d1d5db;

    /* Interactive elements */
    --bn-colour-border-hover: #d1d5db;
    --bn-colour-icon-idle: #c9ccd1;
    --bn-colour-starred: #999;
    --bn-colour-shadow: rgba(0, 0, 0, 0.1);

    /* Focus state */
    --bn-focus-shadow: 0 3px 12px rgba(0,0,0,0.12), 0 0 0 1px rgba(0,0,0,0.05);
    --bn-focus-ring: 0 0 0 2px rgba(0, 122, 255, 0.12);

    /* Hover backgrounds */
    --bn-hover-bg: rgba(0, 0, 0, 0.04);
    --bn-hover-bg-subtle: rgba(0, 0, 0, 0.03);

    /* Selection state */
    --bn-selection-bg: #eef4fc;
    --bn-selection-border: #007aff;
    --bn-selection-bg-inactive: #e5e7eb;
    --bn-selection-border-inactive: #9ca3af;
    /* Sidebar nav selected-row capsule — NSColor unemphasizedSelectedContentBackgroundColor,
       sampled (no canonical Apple hex; dynamic + vibrant composite). Re-sample at OS bumps. */
    --bn-nav-selection-bg: #efefef;

    /* Sidebar overlay */
    --bn-overlay-shadow: 4px 0 16px rgba(0, 0, 0, 0.08);

    /* Legacy aliases */
    --bn-colour-suggestion: #007aff;
    --bn-colour-suggestion-bg: #eff6ff;
}

/* Dark mode — uses light-dark() with the color-scheme property.
   Browsers without light-dark() support (~13%) fall back to the
   plain light values above. */

@supports (color: light-dark(#000, #fff)) {
    :root,
    [data-color-theme="default"] {
        /* Colour palette */
        --bn-colour-bg:               light-dark(#ffffff, #111111);
        --bn-colour-text:             light-dark(#1a1a1a, #e5e7eb);
        --bn-colour-muted:            light-dark(#6b7280, #9ca3af);
        --bn-colour-border:           light-dark(#e5e7eb, #2d2d2d);
        --bn-colour-accent:           light-dark(#007aff, #0a84ff);
        --bn-colour-hover:            light-dark(#e8f0fe, #1e293b);
        --bn-colour-inspector-bg:     light-dark(#f9f9fa, #1c1c1e);   /* Inspector chrome — one step up from the #111 editor (Apple systemGray6 dark) */

        /* Semantic surfaces */
        --bn-colour-quote-bg:         light-dark(#f9fafb, #1a1a1a);
        --bn-colour-badge-bg:         light-dark(#f3f4f6, #252525);
        --bn-colour-badge-text:       light-dark(#374151, #d1d5db);
        --bn-colour-user-tag-bg:      light-dark(#f3f4f6, #252525);
        --bn-colour-user-tag-text:    light-dark(#4b5563, #d1d5db);
        --bn-colour-crop-bg:          light-dark(#fffbe6, #2a2614);
        --bn-crop-handle-colour:      light-dark(#c4850a, #f0b830);
        --bn-crop-handle-hover:       light-dark(#a06d08, #f5cc60);
        --bn-colour-active-bg:        light-dark(#f0fdf4, #0f2918);
        --bn-colour-highlight:        light-dark(#fef08a, #854d0e);
        --bn-colour-cited-bg:         light-dark(#fef9c3, #3b2f05);

        /* Playback-sync glow */
        --bn-glow-colour:             light-dark(rgba(0, 122, 255, 0.06), rgba(10, 132, 255, 0.12));
        --bn-glow-colour-strong:      light-dark(rgba(0, 122, 255, 0.11), rgba(10, 132, 255, 0.2));

        /* Minimap */
        --bn-minimap-quote:           light-dark(#e5e7eb, #333333);
        --bn-minimap-heading:         light-dark(#b0b5bd, #555555);
        --bn-minimap-viewport-bg:     light-dark(rgba(0, 122, 255, 0.15), rgba(10, 132, 255, 0.2));
        --bn-minimap-viewport-border: light-dark(rgba(0, 122, 255, 0.3), rgba(10, 132, 255, 0.4));

        /* Transcript coverage bar */
        --bn-coverage-report:    light-dark(#93b4f4, #4a7ecf);
        --bn-coverage-moderator: light-dark(#d97706, #fbbf24);
        --bn-coverage-omitted:   light-dark(#d1d5db, #4b5563);

        /* Group card — neutral */
        --bn-group-none:      light-dark(#f9fafb, #1e1e1e);

        /* Micro histogram bar — neutral */
        --bn-bar-none:      light-dark(#d1d5db, #4b5563);

        /* Destructive action */
        --bn-colour-negative:         light-dark(#dc2626, #ef4444);

        /* Success and caution */
        --bn-colour-positive:         light-dark(#16a34a, #22c55e);
        --bn-colour-warning:          light-dark(#f59e0b, #fbbf24);

        /* Interactive elements */
        --bn-colour-border-hover:     light-dark(#d1d5db, #4b5563);
        --bn-colour-icon-idle:        light-dark(#c9ccd1, #595959);
        --bn-colour-starred:          light-dark(#999, #ccc);
        --bn-colour-shadow:           light-dark(rgba(0,0,0,0.1), rgba(0,0,0,0.4));

        /* Focus and selection */
        --bn-focus-ring:              light-dark(0 0 0 2px rgba(0, 122, 255, 0.12), 0 0 0 2px rgba(10, 132, 255, 0.2));
        --bn-selection-bg:            light-dark(#eef4fc, #1a2838);
        --bn-selection-border:        light-dark(#007aff, #0a84ff);
        --bn-selection-bg-inactive:     light-dark(#e5e7eb, #262626);
        --bn-selection-border-inactive: light-dark(#9ca3af, #4b5563);
        --bn-nav-selection-bg:          light-dark(#efefef, #2b2b2b);

        /* Hover backgrounds */
        --bn-hover-bg:                light-dark(rgba(0,0,0,0.04), rgba(255,255,255,0.06));
        --bn-hover-bg-subtle:         light-dark(rgba(0,0,0,0.03), rgba(255,255,255,0.04));

        /* Legacy aliases (deprecated) */
        --bn-colour-suggestion:       light-dark(#007aff, #0a84ff);
        --bn-colour-suggestion-bg:    light-dark(#eff6ff, #111d2e);
    }
}

/* ════ bristlenose/theme/colors/palette-edo.css — lines 1–183 ════ */
/* palette-edo — Edo-period Japanese art colour theme.
   Sampled from three artworks seen at the British Museum Samurai exhibition,
   1 Mar 2026. See docs/mockups/edo-colour-palette.html for source analysis.

   Pigments: rokusho (verdigris), sumi (iron-gall ink), cinnabar vermillion,
   bero-ai (Prussian blue), yellow ochre.

   Desktop default. Activate: data-color-theme="edo" on <html>.
   Env/CLI: BRISTLENOSE_PALETTE=edo or --palette edo (canonical; BRISTLENOSE_COLOR_THEME
   is the deprecated alias). Internal <html> attribute stays data-color-theme (glossary §Display settings).

   ── v1 decisions (Jul 2026) ──
   Accent uses Prussian blue's vivid UNDERTONE (#0f5c9e), not the dull masstone
   sampled off aged prints — that masstone reads too low-chroma for links/icons/selection.
   Dark accent is vivid blue (#4d9fe0), not verdigris. Background is bright Paper
   White (#fdfbf7). Body ink is passport navy (#1b2230 / #e8e3d6 dark).

   Alternatives considered — for future edo2/edo3 variants (explore in
   docs/mockups/edo-theme-studio.html):
     paper  — Snow White #fdfbf7, Warm off-white #f0e9d8, Washi Cream #ede5d1 (warmer/more washi)
     accent — masstone Prussian #0f5c9e, midpoint #164e80, electric #2a7ac0; dark verdigris #7ba8a0
     ink    — Sumi Black #1b2230 light / Sail Parchment #d4c9a8 dark; Moonlight #e4e6ea (cool dark ink)
   Known follow-up: warm surfaces (quote-bg #f0e9d8, hover #ede5d1, badge #e8dfc9)
   now read warmer against the brighter paper — revisit surface harmony next pass. */

[data-color-theme="edo"] {
    /* Colour palette — warm paper with indigo/verdigris accents */
    --bn-colour-bg: #fdfbf7;                    /* Paper White — bright near-white */
    --bn-colour-text: #1b2230;                   /* Passport navy — near-black, indigo whisper */
    --bn-colour-muted: #4a698a;                  /* Storm Slate — atmospheric grey-blue (AA 4.5:1 on paper + quote-bg) */
    --bn-colour-border: #d4c9a8;                 /* Sail Parchment — warm border */
    --bn-colour-accent: #0f5c9e;                 /* Vivid Prussian — bero-ai undertone */
    --bn-colour-hover: #ede5d1;                  /* Washi Cream tint — warm hover */
    --bn-colour-inspector-bg: #f7f2e6;           /* Inspector chrome — warm washi; the mirror of Xcode's #f9f9fa (Apple cools the neutral, Edo warms the paper). One notch off Paper White, lighter than quote-bg so it reads as chrome not content */

    /* Semantic surfaces */
    --bn-colour-quote-bg: #f0e9d8;              /* Warm off-white */
    --bn-colour-badge-bg: #e8dfc9;              /* Parchment badge */
    --bn-colour-badge-text: #2d3654;            /* Court Indigo */
    --bn-colour-user-tag-bg: #e8dfc9;
    --bn-colour-user-tag-text: #3d4a5c;
    --bn-colour-crop-bg: #f5ecd0;               /* Gold Ochre tint */
    --bn-crop-handle-colour: #b5432a;           /* Vermillion */
    --bn-crop-handle-hover: #8b3a3a;            /* Bengara Red */
    --bn-colour-active-bg: #e8f0e4;             /* Pine Green tint */
    --bn-colour-highlight: #c4a96a;             /* Gold Ochre highlight */

    /* Destructive action — vermillion */
    --bn-colour-negative: #b5432a;

    /* Success — Pine Green (matsuba-iro), the hue active-bg already tints toward.
       Caution — Gold Ochre, deepened for legibility on paper. */
    --bn-colour-positive: #4a6b4a;
    --bn-colour-warning: #a8842c;

    /* Playback-sync glow — Prussian Blue based */
    --bn-glow-colour: rgba(15, 92, 158, 0.08);
    --bn-glow-colour-strong: rgba(15, 92, 158, 0.15);

    /* Minimap — warm parchment tones */
    --bn-minimap-quote: #d4c9a8;
    --bn-minimap-heading: #9e8b6e;
    --bn-minimap-viewport-bg: rgba(15, 92, 158, 0.12);
    --bn-minimap-viewport-border: rgba(15, 92, 158, 0.25);

    /* Transcript coverage bar */
    --bn-coverage-report: #5a7d9b;
    --bn-coverage-moderator: #c4a96a;
    --bn-coverage-omitted: #d4c9a8;

    /* Group card — neutral */
    --bn-group-none: #f0e9d8;

    /* Micro histogram bar — neutral */
    --bn-bar-none: #c4b898;

    /* Interactive elements */
    --bn-colour-border-hover: #b8ad91;
    --bn-colour-icon-idle: #b8ad91;
    --bn-colour-starred: #9e8b6e;
    --bn-colour-shadow: rgba(30, 20, 10, 0.12);

    /* Focus state */
    --bn-focus-shadow: 0 3px 12px rgba(30, 20, 10, 0.12), 0 0 0 1px rgba(30, 20, 10, 0.06);
    --bn-focus-ring: 0 0 0 2px rgba(15, 92, 158, 0.15);

    /* Hover backgrounds */
    --bn-hover-bg: rgba(30, 20, 10, 0.05);
    --bn-hover-bg-subtle: rgba(30, 20, 10, 0.03);

    /* Selection state — Prussian Blue */
    --bn-selection-bg: #e0e8f0;
    --bn-selection-border: #0f5c9e;
    --bn-selection-bg-inactive: #e8e2d4;
    --bn-selection-border-inactive: #b8ad91;
    /* Sidebar nav selected-row capsule — warm parchment grey (edo's native-grey analogue) */
    --bn-nav-selection-bg: #e6ddc9;

    /* Sidebar overlay */
    --bn-overlay-shadow: 4px 0 16px rgba(30, 20, 10, 0.10);

    /* Legacy aliases */
    --bn-colour-suggestion: #0f5c9e;
    --bn-colour-suggestion-bg: #e0e8f0;
}

/* Dark mode — Sumi Black bg, warm parchment text */

@supports (color: light-dark(#000, #fff)) {
    [data-color-theme="edo"] {
        /* Colour palette */
        --bn-colour-bg:               light-dark(#fdfbf7, #1a1816);
        --bn-colour-text:             light-dark(#1b2230, #e8e3d6);
        --bn-colour-muted:            light-dark(#4a698a, #7ba8a0);
        --bn-colour-border:           light-dark(#d4c9a8, #2d2820);
        --bn-colour-accent:           light-dark(#0f5c9e, #4d9fe0);
        --bn-colour-hover:            light-dark(#ede5d1, #252118);
        --bn-colour-inspector-bg:     light-dark(#f7f2e6, #211e18);   /* Inspector chrome — warm washi light / one warm step off Sumi dark */

        /* Semantic surfaces */
        --bn-colour-quote-bg:         light-dark(#f0e9d8, #211e18);
        --bn-colour-badge-bg:         light-dark(#e8dfc9, #2d2820);
        --bn-colour-badge-text:       light-dark(#2d3654, #c4b898);
        --bn-colour-user-tag-bg:      light-dark(#e8dfc9, #2d2820);
        --bn-colour-user-tag-text:    light-dark(#3d4a5c, #c4b898);
        --bn-colour-crop-bg:          light-dark(#f5ecd0, #2d2614);
        --bn-crop-handle-colour:      light-dark(#b5432a, #e06a4a);
        --bn-crop-handle-hover:       light-dark(#8b3a3a, #e88a6a);
        --bn-colour-active-bg:        light-dark(#e8f0e4, #1a2818);
        --bn-colour-highlight:        light-dark(#c4a96a, #6b5528);
        --bn-colour-cited-bg:         light-dark(#f5ecd0, #3b3010);

        /* Playback-sync glow */
        --bn-glow-colour:             light-dark(rgba(15, 92, 158, 0.08), rgba(77, 159, 224, 0.10));
        --bn-glow-colour-strong:      light-dark(rgba(15, 92, 158, 0.15), rgba(77, 159, 224, 0.18));

        /* Minimap */
        --bn-minimap-quote:           light-dark(#d4c9a8, #2d2820);
        --bn-minimap-heading:         light-dark(#9e8b6e, #4a4030);
        --bn-minimap-viewport-bg:     light-dark(rgba(15, 92, 158, 0.12), rgba(77, 159, 224, 0.15));
        --bn-minimap-viewport-border: light-dark(rgba(15, 92, 158, 0.25), rgba(77, 159, 224, 0.3));

        /* Transcript coverage bar */
        --bn-coverage-report:    light-dark(#5a7d9b, #4a6a80);
        --bn-coverage-moderator: light-dark(#c4a96a, #a08848);
        --bn-coverage-omitted:   light-dark(#d4c9a8, #3d3830);

        /* Group card — neutral */
        --bn-group-none:      light-dark(#f0e9d8, #211e18);

        /* Micro histogram bar — neutral */
        --bn-bar-none:      light-dark(#c4b898, #4a4030);

        /* Destructive action — vermillion */
        --bn-colour-negative:         light-dark(#b5432a, #e06a4a);

        /* Success — Pine Green; caution — Gold Ochre */
        --bn-colour-positive:         light-dark(#4a6b4a, #7fa87f);
        --bn-colour-warning:          light-dark(#a8842c, #c4a96a);

        /* Interactive elements */
        --bn-colour-border-hover:     light-dark(#b8ad91, #4a4030);
        --bn-colour-icon-idle:        light-dark(#b8ad91, #4a4030);
        --bn-colour-starred:          light-dark(#9e8b6e, #b8a880);
        --bn-colour-shadow:           light-dark(rgba(30,20,10,0.12), rgba(0,0,0,0.4));

        /* Focus and selection */
        --bn-focus-ring:              light-dark(0 0 0 2px rgba(15, 92, 158, 0.15), 0 0 0 2px rgba(77, 159, 224, 0.2));
        --bn-selection-bg:            light-dark(#e0e8f0, #1e2830);
        --bn-selection-border:        light-dark(#0f5c9e, #4d9fe0);
        --bn-selection-bg-inactive:     light-dark(#e8e2d4, #26231d);
        --bn-selection-border-inactive: light-dark(#b8ad91, #4a4030);
        --bn-nav-selection-bg:          light-dark(#e6ddc9, #2d2922);

        /* Hover backgrounds */
        --bn-hover-bg:                light-dark(rgba(30,20,10,0.05), rgba(212,201,168,0.06));
        --bn-hover-bg-subtle:         light-dark(rgba(30,20,10,0.03), rgba(212,201,168,0.04));

        /* Legacy aliases */
        --bn-colour-suggestion:       light-dark(#0f5c9e, #4d9fe0);
        --bn-colour-suggestion-bg:    light-dark(#e0e8f0, #1e2830);
    }
}

/* ════ bristlenose/theme/atoms/badge.css — lines 1–326 ════ */
/* Atom: badge — base badge, sentiment variants, AI and user variants */

/* Every tag is one weight, separated from its kind by colour, not weight:
   --bn-weight-mono-tag, 460 in the light appearance and 400 in dark. It was 370
   (Light), which drew Light only on a Mac with Apple's SF Mono download and
   Regular almost everywhere else (docs/design-monospace-roles.md §6). */
.badge {
    display: inline-block;
    font-family: var(--bn-font-mono);
    font-size: var(--bn-text-badge);
    font-weight: var(--bn-weight-mono-tag);
    padding: var(--bn-space-xs) 0.45rem;
    border-radius: var(--bn-radius-sm);
    background: var(--bn-colour-badge-bg);
    color: var(--bn-colour-badge-text);
}

/* Sentiment variants (v0.7+ taxonomy) — see docs/academic-sources.html */
.badge-frustration { background: var(--bn-sentiment-frustration-bg); color: var(--bn-sentiment-frustration); }
.badge-confusion { background: var(--bn-sentiment-confusion-bg); color: var(--bn-sentiment-confusion); }
.badge-doubt { background: var(--bn-sentiment-doubt-bg); color: var(--bn-sentiment-doubt); }
.badge-surprise { background: var(--bn-sentiment-surprise-bg); color: var(--bn-sentiment-surprise); }
.badge-satisfaction { background: var(--bn-sentiment-satisfaction-bg); color: var(--bn-sentiment-satisfaction); }
.badge-delight { background: var(--bn-sentiment-delight-bg); color: var(--bn-sentiment-delight); }
.badge-confidence { background: var(--bn-sentiment-confidence-bg); color: var(--bn-sentiment-confidence); }

/* Legacy variants (deprecated — kept for backward compat with old intermediate JSON) */
.badge-suggestion { background: var(--bn-colour-suggestion-bg); color: var(--bn-colour-suggestion); }
.badge-frustrated { background: var(--bn-sentiment-frustration-bg); color: var(--bn-sentiment-frustration); }
.badge-delighted { background: var(--bn-sentiment-delight-bg); color: var(--bn-sentiment-delight); }
.badge-confused { background: var(--bn-sentiment-confusion-bg); color: var(--bn-sentiment-confusion); }
.badge-amused { background: var(--bn-sentiment-delight-bg); color: var(--bn-sentiment-delight); }
.badge-critical { background: var(--bn-sentiment-frustration-bg); color: var(--bn-sentiment-frustration); }
.badge-sarcastic { background: var(--bn-colour-badge-bg); color: var(--bn-colour-badge-text); }
.badge-judgment { background: var(--bn-colour-badge-bg); color: var(--bn-colour-badge-text); }
.badge-narration { background: var(--bn-colour-badge-bg); color: var(--bn-colour-badge-text); }
.badge-task_management { background: var(--bn-colour-badge-bg); color: var(--bn-colour-badge-text); }

/* AI badge — deletable on hover */
.badge-ai {
    cursor: pointer;
    position: relative;
    transition: opacity var(--bn-transition-fast);
}

.badge-ai:hover {
    opacity: 0.8;
}

/* Delete circle — white floating chip with grey ×.
   Pure flexbox centering (10c-fix2 approach).
   TODO: replace × character with SVG icon for cross-platform consistency. */
.badge-ai::after {
    content: "\00d7";
    position: absolute;
    top: calc(-0.3rem - 1px);
    right: calc(-0.3rem - 1px);
    width: calc(0.875rem + 0.5px);   /* ~14.5px */
    height: calc(0.875rem + 0.5px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    background: var(--bn-colour-bg);
    color: var(--bn-colour-negative);
    border-radius: 50%;
    font-size: var(--bn-text-micro);
    font-weight: var(--bn-weight-strong);
    line-height: 1;
    opacity: 0;
    transition: opacity var(--bn-transition-fast);
    pointer-events: none;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.16), 0 0 1px rgba(0, 0, 0, 0.06);
}

.badge-ai:hover::after {
    opacity: 1;
}

/* User tag — mode-dependent treatment.
   Light mode: dark text on washed codebook bg (pale tint).
   Dark mode: white text on saturated codebook bg.
   Background colour set via inline style from codebook.js.
   Falls back to --bn-colour-user-tag-bg when no codebook colour assigned. */
.badge-user {
    background: var(--bn-colour-user-tag-bg);
    color: var(--bn-colour-text);
    cursor: default;
    position: relative;
}

/* Dark mode: user tags switch to white-on-saturated */
@supports (color: light-dark(#000, #fff)) {
    [data-theme="dark"] .badge-user {
        color: #ffffff;
    }
    @media (prefers-color-scheme: dark) {
        :root:not([data-theme="light"]) .badge-user {
            color: #ffffff;
        }
    }
}

/* AI tag visibility toggle */
body.hide-ai-tags .badge-ai { display: none; }

.badge-user .badge-delete {
    position: absolute;
    top: calc(-0.3rem - 1px);
    right: calc(-0.3rem - 1px);
    width: calc(0.875rem + 0.5px);   /* ~14.5px */
    height: calc(0.875rem + 0.5px);
    background: var(--bn-colour-bg);
    border: none;
    border-radius: 50%;
    color: var(--bn-colour-negative);
    font-size: var(--bn-text-micro);
    font-weight: var(--bn-weight-strong);
    --bn-icon-stem: var(--bn-icon-stem-strong);  /* its icon follows the text weight */
    line-height: 1;
    cursor: pointer;
    opacity: 0;
    transition: opacity var(--bn-transition-fast);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    pointer-events: none;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.16), 0 0 1px rgba(0, 0, 0, 0.06);
}

.badge-user:hover .badge-delete {
    opacity: 1;
    pointer-events: auto;
}

/* Add-tag ghost button */
.badge-add {
    border: 1px dashed var(--bn-colour-border);
    background: transparent;
    color: var(--bn-colour-muted);
    cursor: pointer;
    transition: border-color var(--bn-transition-fast), color var(--bn-transition-fast);
    user-select: none;
}

.badge-add:hover {
    border-color: var(--bn-colour-accent);
    color: var(--bn-colour-accent);
}

/* Proposed badge — pulsating dashed border (AutoCode) */
@keyframes bn-proposed-pulse {
    0%   { opacity: 0.50; }
    50%  { opacity: 0.78; }
    100% { opacity: 0.50; }
}

.badge-proposed {
    animation: bn-proposed-pulse 3s ease-in-out infinite;
    border: 1px dashed currentColor;
    cursor: pointer;
    position: relative;
}

.badge-proposed:hover {
    animation: none;
    opacity: 1 !important;
}

/* Action pill — floating [✗ | ✓] bar at badge top-right.
   ✗ (deny) anchored at delete-circle position, ✓ (accept) hangs right.
   16px compartments, pill-shaped, appears on hover. */
.badge-action-pill {
    position: absolute;
    top: calc(-0.3rem - 1px);              /* same vertical as delete × */
    right: calc(-0.3rem - 1px - 1rem);     /* ✗ aligns with delete × position,
                                              ✓ extends past badge right edge */
    display: flex;
    gap: 0;
    background: var(--bn-colour-bg);
    border-radius: var(--bn-radius-pill);   /* clamps to half-height; survives a height change */
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.16), 0 0 1px rgba(0, 0, 0, 0.06);
    opacity: 0;
    transition: opacity var(--bn-transition-fast);
    pointer-events: none;
    overflow: hidden;
    z-index: 1;                              /* sit above adjacent badges */
}

.badge-proposed:hover .badge-action-pill,
.badge-proposed:focus-within .badge-action-pill {
    opacity: 1;
    pointer-events: auto;
}

.badge-action-deny,
.badge-action-accept {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1rem;       /* 16px */
    height: 1rem;
    font-size: var(--bn-text-micro);
    font-weight: var(--bn-weight-strong);
    --bn-icon-stem: var(--bn-icon-stem-strong);  /* its icon follows the text weight */
    cursor: pointer;
    border: none;
    background: transparent;
    padding: 0;
    transition: background var(--bn-transition-fast);
}

.badge-action-deny {
    color: var(--bn-colour-negative);
}

.badge-action-accept {
    color: var(--bn-colour-positive);
    border-left: 1px solid var(--bn-colour-border);
}

.badge-action-deny:hover { background: #fef2f2; }
.badge-action-accept:hover { background: #dcfce7; }

/* Keyboard focus ring — inset (outline-offset negative) because the pill has
   overflow:hidden, which would clip an outset ring on these 16px buttons. */
.badge-action-deny:focus-visible,
.badge-action-accept:focus-visible {
    outline: 2px solid var(--bn-colour-accent);
    outline-offset: -2px;
}

/* Dark mode: pill and action compartments */
@supports (color: light-dark(#000, #fff)) {
    [data-theme="dark"] .badge-action-pill {
        background: var(--bn-colour-bg);
    }
    [data-theme="dark"] .badge-action-deny:hover {
        background: rgba(220, 38, 38, 0.25);
        color: #f87171;
    }
    [data-theme="dark"] .badge-action-accept:hover {
        background: rgba(22, 163, 74, 0.25);
        color: #4ade80;
    }
    @media (prefers-color-scheme: dark) {
        :root:not([data-theme="light"]) .badge-action-pill {
            background: var(--bn-colour-bg);
        }
        :root:not([data-theme="light"]) .badge-action-deny:hover {
            background: rgba(220, 38, 38, 0.25);
            color: #f87171;
        }
        :root:not([data-theme="light"]) .badge-action-accept:hover {
            background: rgba(22, 163, 74, 0.25);
            color: #4ade80;
        }
    }
}

/* Accept flash — brief brightness burst when a proposed tag is accepted.
   Applied by React (QuoteCard) on the new user badge for ~400ms. */
@keyframes badge-accept-flash {
    0%   { filter: brightness(1.35); }
    100% { filter: brightness(1); }
}

.badge-accept-flash {
    animation: badge-accept-flash 0.4s ease-out;
}

/* Badge animations */
@keyframes badge-fade-out {
    to { opacity: 0; transform: scale(0.8); }
}

.badge-removing {
    animation: badge-fade-out 0.15s ease-out forwards;
    pointer-events: none;
}

@keyframes badge-fade-in {
    from { opacity: 0; transform: scale(0.8); }
    to   { opacity: 1; transform: scale(1); }
}

.badge-appearing {
    animation: badge-fade-in 0.15s ease-out;
}

/* Bulk-tag flash — asymmetric highlight (0.2s in, 0.6s hold+out).
   Uses box-shadow spread to avoid overriding codebook background colour. */
@keyframes badge-bulk-flash {
    0%   { box-shadow: 0 0 0 0 var(--bn-selection-border); }
    25%  { box-shadow: 0 0 0 3px var(--bn-selection-border); }
    100% { box-shadow: 0 0 0 0 var(--bn-selection-border); }
}

.badge-bulk-flash {
    animation: badge-bulk-flash 0.8s ease-out;
}

/* "New" material marker — a body-sized highlighter shown inline after a
   section/theme title (Phase 3, 3c).  Placeholder styling; click to dismiss
   (it evaporates, no undo — it has served its purpose once noticed). */
.bn-new-badge {
    display: inline;
    margin-left: 0.4rem;
    padding: 0.05em 0.3em;
    border: none;
    border-radius: var(--bn-radius-sm);
    background: var(--bn-colour-new-highlight);
    color: var(--bn-colour-new-highlight-text);
    font-family: inherit;
    font-size: var(--bn-text-body);
    font-weight: var(--bn-weight-emphasis);
    line-height: 1;
    cursor: pointer;
    vertical-align: baseline;
}
.bn-new-badge:hover { filter: brightness(0.95); }
.bn-new-badge:focus-visible {
    outline: 2px solid var(--bn-colour-accent);
    outline-offset: 1px;
}

/* ════ bristlenose/theme/organisms/session-tapestry.css — lines 1–355 ════ */
/* Session tapestry — the timeline slice under a row of the Sessions grid
   (frontend/src/components/SessionTapestry.tsx). Lanes: section flags, speaker
   clips, sentiment bars, theme spans. Every colour and size is a shipped token
   except the three marked NEW. Type sizes and popover padding go through
   --bn-tp-* variables that default to the shipped tokens; the values live in
   frontend/src/utils/tapestryTuning.ts, and the dev
   playground moves them along the existing ladders only. Design + measurements:
   experiments/session-tapestry/README.md. */

:root {
    /* NEW: resting section flag — the page background with a 6% tint, so the
       raised flag (pure background + shadow) reads as in front. */
    --bn-tp-flag-rest: color-mix(in srgb, var(--bn-colour-bg) 94%, var(--bn-colour-text));
    /* NEW: hover tint on the quote popover (4%), the sign that it opens the transcript. */
    --bn-tp-popover-hover: color-mix(in srgb, var(--bn-colour-bg) 96%, var(--bn-colour-text));
}

/* Disclosure, inside the ID cell — no new grid column, so the width ladder is untouched. */
.bn-tapestry-toggle {
    all: unset;
    display: inline-grid;
    place-items: center;
    width: 16px;
    height: 16px;
    margin: 0 2px 0 -4px;
    vertical-align: -2px;
    border-radius: var(--bn-radius-sm);
    color: var(--bn-colour-muted);
    cursor: pointer;
}
.bn-tapestry-toggle:hover { color: var(--bn-colour-text); }
.bn-tapestry-toggle:focus-visible { outline: 2px solid var(--bn-colour-accent); outline-offset: 1px; }
.bn-tapestry-toggle svg { transition: transform 0.15s ease; }
.bn-tapestry-toggle[aria-expanded="true"] svg { transform: rotate(90deg); }

/* An open session reads as one unit: its row and its slice share the tint, with no
   keyline between them; the keyline and a band of empty space come after the slice,
   before the next session. */
.bn-sessions-row.bn-tapestry-open {
    background: var(--bn-colour-quote-bg);
    border-bottom-color: transparent;
}
/* Hover would tint the row alone and split the unit (beats the grid's 0-3-0 hover rule). */
.bn-sessions-row.bn-tapestry-open[data-session]:hover { background: var(--bn-colour-quote-bg); }

/* The slice: a full-width grid item after its row. */
.bn-tapestry {
    grid-column: 1 / -1;
    min-width: 0;
    background: var(--bn-colour-quote-bg);
    border-bottom: 1px solid var(--bn-colour-border);
    margin-bottom: var(--bn-space-lg);
}
.bn-tapestry-cell { min-width: 0; }
.bn-tapestry-scroll {
    padding: var(--bn-space-sm) 0;
    /* Room under the timecodes for the horizontal scrollbar: macOS draws an overlay
       bar over the content (~11px, ~15px while hovered), so it would cover them. */
    padding-bottom: calc(var(--bn-space-sm) + 14px);
    overflow-x: auto;
}
.bn-tapestry-svg { display: block; }

/* Lane labels read as headings: the column headers' face, weight and ink
   (.bn-sessions-head), one stop down the ladder. */
.bn-tp-lane {
    font: var(--bn-weight-emphasis) var(--bn-tp-text-lane, var(--bn-text-caption)) var(--bn-font-body);
    fill: var(--bn-colour-text);
}
.bn-tp-tick {
    font: var(--bn-tp-text-tick, var(--bn-text-micro)) var(--bn-font-mono);
    fill: var(--bn-colour-muted);
}
/* The tick nearest the hover playhead, in the timecode blue: about where a click lands. */
.bn-tp-tick.near { fill: var(--bn-colour-accent); }
.bn-tp-track { fill: var(--bn-colour-badge-bg); }
/* Without video the clips fall back to neutral greys; the track says who speaks. */
.bn-tp-clip-team { fill: var(--bn-colour-border-hover); }
.bn-tp-clip-ppt { fill: var(--bn-colour-muted); }
.bn-tp-clip[data-video] { stroke: rgb(0 0 0 / 0.25); stroke-width: 0.75; }
/* The scene strip — what was on screen, moment by moment (utils/scene_strip.py) — runs inside
   the clips at an opacity. The opacity is the design: the clip keeps its colour and the track its
   identity, and only change shows. The clip's edge is redrawn over it so a striped clip keeps its
   outline. */
.bn-tp-strip { pointer-events: none; }
.bn-tp-strip-ppt { opacity: 0.7; }
.bn-tp-strip-team { opacity: 0.75; }
.bn-tp-clip-edge { fill: none; stroke: rgb(0 0 0 / 0.25); stroke-width: 0.75; pointer-events: none; }
/* A notch where the scene changed: a short hairline just above the tracks, in the text ink. */
.bn-tp-notch { stroke: var(--bn-colour-text); stroke-width: 1; opacity: 0.6; pointer-events: none; }
.bn-tp-clip-label {
    font: var(--bn-weight-emphasis) var(--bn-tp-text-clip, var(--bn-text-badge)) var(--bn-font-body);
    pointer-events: none;
}
/* Neutral clips only; a scene-coloured clip's ink is chosen in JS by WCAG contrast. */
.bn-tp-clip-label.on-team { fill: var(--bn-colour-text); }
.bn-tp-clip-label.on-ppt { fill: light-dark(#fff, #111); }

.bn-tp-flag { cursor: pointer; }
/* The staff and the banner share one hairline: the border keyline at rest, the text
   ink when raised — darker, never thicker. */
.bn-tp-flag line,
.bn-tp-flag path { stroke: var(--bn-colour-border); stroke-width: 1; }
.bn-tp-flag path { fill: var(--bn-tp-flag-rest); }
.bn-tp-flag.raised line,
.bn-tp-flag.raised path { stroke: var(--bn-colour-text); }
.bn-tp-flag.raised path { fill: var(--bn-colour-bg); }
/* Directly under the pointer: the app's selected blue — ink and wash — on the same
   hairline, so it is clear a click goes there. */
.bn-tp-flag.hot line,
.bn-tp-flag.hot path { stroke: var(--bn-selection-border); }
.bn-tp-flag.hot path { fill: var(--bn-selection-bg); }
/* The label keeps the text ink: blue text on the selection wash is 3.6:1. The blue staff,
   hairline and wash carry the state. */
.bn-tp-flag text {
    font: var(--bn-weight-emphasis) var(--bn-tp-text-flag, var(--bn-text-label)) var(--bn-font-body);
    fill: var(--bn-colour-text);
}
.bn-tp-hit { cursor: pointer; }
.bn-tp-playhead { stroke: var(--bn-colour-accent); stroke-width: 1; pointer-events: none; }

.bn-tp-axis { stroke: var(--bn-colour-muted); stroke-width: 0.8; }
.bn-tp-bar { cursor: pointer; transition: opacity 0.12s; }
.bn-tp-bar:focus { outline: none; }
.bn-tp-bar.sel { stroke: var(--bn-colour-text); stroke-width: 1.25; }
/* Focus is its own ring, so a keyboard user can tell it from the selection. */
.bn-tp-bar:focus-visible { stroke: var(--bn-colour-accent); stroke-width: 2; }
/* 0.4, not lower: a dimmed bar is still a control and must keep 3:1 (WCAG 1.4.11). */
.bn-tp-bar.dim { opacity: 0.4; }
.bn-tp-unrated { fill: var(--bn-colour-muted); }
/* The invisible, wider click target over each sentiment mark (pointer only). */
.bn-tp-bar-hit { fill: transparent; cursor: pointer; }

.bn-tp-span { fill: var(--bn-colour-muted); opacity: 0.5; }
/* The chip's fill is a gradient set inline (solid, then fading out over its last 20%), so
   only its left edge is hard — on the timecode where the theme starts. */
.bn-tp-tag { fill: var(--bn-colour-badge-bg); }
/* Sans, not mono: monospace is reserved for tag text, and a theme is not a tag. */
.bn-tp-tag-text {
    font: var(--bn-weight-normal) var(--bn-tp-text-theme, var(--bn-text-label)) var(--bn-font-body);
    fill: var(--bn-colour-badge-text);
}

/* Quote popover: floats under the selected bar, over the themes track, with an
   arrow on the bar — a Mac popover. The whole popover opens the transcript; the
   faint hover tint is the affordance. Shadow: the focused-card token. */
.bn-tp-wrap { position: relative; }
.bn-tp-popover {
    position: absolute;
    z-index: 20;
    box-sizing: border-box;
    padding: var(--bn-tp-pad-popover, var(--bn-space-md));
    background: var(--bn-colour-bg);
    border-radius: var(--bn-radius-lg);
    box-shadow: var(--bn-focus-shadow);
    cursor: pointer;
    transition: background-color 0.12s ease;
}
/* The arrow: a square turned 45°, sharing the popover's ground (so it takes the
   hover tint too) and its hairline on the two outward edges. */
.bn-tp-popover::before {
    content: "";
    position: absolute;
    top: -6px;
    left: calc(var(--bn-tp-arrow-x, 24px) - 6px);
    width: 12px;
    height: 12px;
    background: inherit;
    transform: rotate(45deg);
    box-shadow: -1px -1px 0 rgba(0, 0, 0, 0.05);
    border-top-left-radius: 2px;
}
.bn-tp-popover:hover { background: var(--bn-tp-popover-hover); }
/* --bn-focus-shadow has no dark value, and a dark shadow on a dark ground is no
   edge at all; dark mode adds a faint light hairline instead. */
.bn-tp-popover { outline: 1px solid light-dark(transparent, rgb(255 255 255 / 0.1)); }
.bn-tp-popover::before { box-shadow: -1px -1px 0 light-dark(rgba(0, 0, 0, 0.05), rgb(255 255 255 / 0.1)); }
.bn-tp-meta {
    display: flex;
    align-items: center;
    gap: var(--bn-space-sm);
    flex-wrap: wrap;
    padding-right: 72px; /* room for prev / next / close */
    font-size: var(--bn-tp-text-pop-meta, var(--bn-text-caption));
    color: var(--bn-colour-muted);
}
.bn-tp-tc {
    all: unset;
    font-family: var(--bn-font-mono);
    color: var(--bn-colour-muted);
    cursor: pointer;
    border-radius: var(--bn-radius-sm);
}
.bn-tp-tc:hover { color: var(--bn-colour-text); }
.bn-tp-tc:focus-visible { outline: 2px solid var(--bn-colour-accent); outline-offset: 1px; }
.bn-tp-popover blockquote {
    margin: var(--bn-space-sm) 0 0;
    font-size: var(--bn-tp-text-pop-quote, var(--bn-text-body));
    line-height: 1.5;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 4;
    line-clamp: 4;
    overflow: hidden;
}
.bn-tp-actions {
    position: absolute;
    top: 6px;
    right: 6px;
    display: flex;
    align-items: center;
}
.bn-tp-close {
    all: unset;
    width: 22px;
    height: 22px;
    display: grid;
    place-items: center;
    border-radius: var(--bn-radius-sm);
    color: var(--bn-colour-muted);
    cursor: pointer;
}
.bn-tp-close:hover { color: var(--bn-colour-text); }
.bn-tp-close:focus-visible { outline: 2px solid var(--bn-colour-accent); outline-offset: -2px; }
.bn-tp-close svg { width: 10px; height: 10px; }

/* Previous / next: bristlenose.app's homepage carousel buttons, at 12 px (from
   26) inside a 22 px hit area, revealed on hover or keyboard focus as there. */
.bn-tp-nav { display: flex; }
.bn-tp-nav button {
    all: unset;
    width: 22px;
    height: 22px;
    display: grid;
    place-items: center;
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.15s ease-in-out;
    color: var(--bn-colour-text);
}
.bn-tp-nav button > span {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 1px solid rgba(0, 0, 0, 0.08);
    background: rgba(255, 255, 255, 0.72);
    -webkit-backdrop-filter: blur(12px) saturate(1.5);
    backdrop-filter: blur(12px) saturate(1.5);
    box-shadow: 0 0.5px 1px rgba(0, 0, 0, 0.15);
    display: grid;
    place-items: center;
}
.bn-tp-nav svg { width: 6px; height: 6px; }
.bn-tp-nav button:disabled > span { opacity: 0.35; }
.bn-tp-popover:hover .bn-tp-nav button,
.bn-tp-popover:focus-within .bn-tp-nav button { opacity: 1; pointer-events: auto; }
.bn-tp-nav button:focus-visible > span { outline: 2px solid var(--bn-colour-accent); outline-offset: 1px; }
@media (prefers-color-scheme: dark) {
    .bn-tp-nav button > span { background: rgba(40, 40, 40, 0.72); border-color: rgba(255, 255, 255, 0.1); }
}

/* NEW: zoom — a mini slider between magnifiers (Photos, the Final Cut timeline),
   in the section heading's action slot; no range control ships elsewhere. */
.bn-tp-zoom { display: flex; align-items: center; gap: 2px; }
.bn-tp-zoom-btn {
    all: unset;
    width: 16px;
    height: 16px;
    display: grid;
    place-items: center;
    border-radius: var(--bn-radius-sm);
    color: var(--bn-colour-muted);
    cursor: pointer;
}
.bn-tp-zoom-btn:hover { color: var(--bn-colour-text); }
.bn-tp-zoom-btn:disabled { opacity: 0.4; cursor: default; }
.bn-tp-zoom-btn:focus-visible { outline: 2px solid var(--bn-colour-accent); outline-offset: 1px; }
.bn-tp-zoom-btn svg { width: 12px; height: 12px; }
.bn-tp-zoom-slider {
    -webkit-appearance: none;
    appearance: none;
    width: 64px;
    height: 14px;
    margin: 0 2px;
    background: none;
}
.bn-tp-zoom-slider:focus-visible { outline: 2px solid var(--bn-colour-accent); outline-offset: 1px; }
/* Track and thumb ring meet 3:1 against the page (WCAG 1.4.11). */
.bn-tp-zoom-slider::-webkit-slider-runnable-track { height: 3px; border-radius: 2px; background: var(--bn-colour-muted); }
.bn-tp-zoom-slider::-moz-range-track { height: 3px; border-radius: 2px; background: var(--bn-colour-muted); }
.bn-tp-zoom-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 11px;
    height: 11px;
    margin-top: -4px;
    border-radius: 50%;
    background: light-dark(#fff, #d8d8dc);
    box-shadow: 0 0 0 1px var(--bn-colour-muted), 0 1px 2px rgb(0 0 0 / 0.25);
}
.bn-tp-zoom-slider::-moz-range-thumb {
    width: 11px;
    height: 11px;
    border: 0;
    border-radius: 50%;
    background: light-dark(#fff, #d8d8dc);
    box-shadow: 0 0 0 1px var(--bn-colour-muted), 0 1px 2px rgb(0 0 0 / 0.25);
}

@media (prefers-reduced-motion: reduce) {
    .bn-tapestry-toggle svg,
    .bn-tp-bar,
    .bn-tp-popover,
    .bn-tp-nav button { transition: none; }
}

@media print {
    .bn-tapestry-toggle,
    .bn-tp-zoom { display: none; }
}

/* ── Hover thumbnail: a still of the participant's screen below the speaker lane ──
   (utils/tapestryThumb.ts). Fixed on document.body, so the slice's scroll cannot clip it;
   the popover's ground and shadow; never takes the pointer. */
.bn-tp-thumb {
    position: fixed;
    z-index: 20;
    padding: 3px;
    background: var(--bn-colour-bg);
    border: 1px solid var(--bn-colour-border);
    border-radius: var(--bn-radius-md);
    box-shadow: var(--bn-focus-shadow);
    pointer-events: none;
    animation: bn-tp-thumb-in 0.12s ease;
}
.bn-tp-thumb img {
    display: block;
    width: var(--bn-tp-thumb-w, 160px);
    height: auto;
    border-radius: calc(var(--bn-radius-md) - 2px);
}
.bn-tp-thumb-tc {
    display: block;
    padding: 3px 3px 0;
    font: var(--bn-text-micro) var(--bn-font-mono);
    color: var(--bn-colour-muted);
}
@keyframes bn-tp-thumb-in {
    from { opacity: 0; transform: translateY(-3px); }
}
@media (prefers-reduced-motion: reduce) {
    .bn-tp-thumb { animation: none; }
}
/* The stretch of the participant track the frame stands for. */
.bn-tp-thumb-src { fill: none; stroke: var(--bn-colour-accent); stroke-width: 1.5; pointer-events: none; }
